use vstd::prelude::*;

verus! {

/// Mathematical sign-classification for an `i8` value.
/// (Used for specs; returns an `i8` in {-1,0,1}.)
spec fn sign_i8(a: i8) -> i8 {
    if a < 0 { -1 } else if a == 0 { 0 } else { 1 }
}

/// Postcondition describing the required relationship between `x` and `result`.
spec fn sign_vec_spec(x: Seq<i8>, result: Seq<i8>) -> bool {
    result.len() == x.len()
    && forall|i: int| 0 <= i < x.len() ==> result[i] == sign_i8(x[i])
}

fn sign(x: Vec<i8>) -> (result: Vec<i8>)
    requires
        x.len() > 0,
    ensures
        sign_vec_spec(x@, result@),
{
    let n = x.len();
    let mut result: Vec<i8> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            n == x.len(),
            i <= n,
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result@[j] == sign_i8(x@[j]),
        decreases
            n - i,
    {
        let a = x[i];
        let s: i8 = if a < 0 {
            -1
        } else if a == 0 {
            0
        } else {
            1
        };

        // This establishes the per-element relationship for the new element.
        assert(s == sign_i8(a));

        result.push(s);
        i = i + 1;
    }

    result
}

} // verus!

